import 'dart:async';
import 'dart:convert';
import 'dart:io';
import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import '../lib/health/universal_health.dart';
import '../lib/health/health_history_io.dart';
import '../lib/health/health_panel.dart';
import '../lib/health/health_diagnostics.dart';
import '../lib/storage/windows_sqlite_store.dart';

class MemoryHistory implements HealthHistoryStore {
  final data=<String,List<HealthEvent>>{};
  bool fail=false;
  @override Future<List<HealthEvent>> load(HealthContext c)async=>data[c.fingerprint]??[];
  @override Future<void> save(HealthContext c,List<HealthEvent> events)async{if(fail)throw StateError('private/secret');data[c.fingerprint]=List.of(events);}
}
void main(){
 const school=HealthContext('school-A','profile-A');
 late UniversalHealth engine;late MemoryHistory store;late DateTime time;
 setUp(()async{time=DateTime.utc(2026,10,11);store=MemoryHistory();engine=UniversalHealth(now:()=>time,store:store);await engine.bind(school);});
 tearDown(()async=>engine.dispose());
 void provider({HealthFailure failure=HealthFailure.worker,Future<void> Function(RecoveryLease)? execute,Future<bool> Function(RecoveryLease)? precondition,Future<bool> Function(RecoveryLease)? verify,Duration timeout=const Duration(seconds:1)}){
  engine.register(HealthProvider(id:'documents',version:'2.0',check:(_)async=>HealthObservation(HealthState.degraded,failure:failure),playbooks:[RecoveryPlaybook(id:'restart-derived-worker',kind:RecoveryKind.statelessWorker,failures:{failure},precondition:precondition??((_)async=>true),execute:execute??((_)async{}),verify:verify??((_)async=>true),cooldown:const Duration(milliseconds:100),timeout:timeout)]));
  engine.observe('documents',HealthObservation(HealthState.degraded,failure:failure,operation:'original-private-operation'));
 }
 test('unverified and expired health never becomes healthy',(){engine.register(HealthProvider(id:'future-engine',version:'2.0',check:(_)async=>const HealthObservation(HealthState.unknown)));engine.observe('future-engine',const HealthObservation(HealthState.healthy));expect(engine.overall,HealthState.unknown);engine.observe('future-engine',HealthObservation(HealthState.healthy,verifiedAt:time));expect(engine.overall,HealthState.healthy);time=time.add(const Duration(minutes:6));expect(engine.overall,HealthState.unknown);});
 test('future provider validation rejects duplicates, oversized and invalid contracts',(){provider();expect(()=>provider(),throwsArgumentError);expect(()=>engine.register(HealthProvider(id:'secret/name',version:'2.0',check:(_)async=>const HealthObservation(HealthState.unknown))),throwsArgumentError);});
 test('verified stateless recovery preserves all protected input and operation IDs',()async{final data={'student':'s','fees':100,'attendance':['original'],'queue':[{'operationId':'immutable','revision':4}],'photo':[1,2,3]};final before=jsonEncode(data);provider(execute:(lease)async{lease.check();expect(lease.operation,'original-private-operation');});expect(await engine.recover('documents'),true);expect(jsonEncode(data),before);expect(engine.history.last.stage,'verified');expect(jsonEncode(engine.history.map((e)=>e.toJson()).toList()),isNot(contains('private-operation')));});
 for(final failure in [HealthFailure.authorization,HealthFailure.identity,HealthFailure.conflict,HealthFailure.configuration,HealthFailure.storage,HealthFailure.corrupt,HealthFailure.offline,HealthFailure.unknown]) {
  test('${failure.name} never invokes an automatic or manual unsafe retry',()async{var calls=0;provider(failure:failure,execute:(_)async{calls++;});expect(await engine.recover('documents'),false);expect(await engine.recover('documents',automatic:false),false);expect(calls,0);});
 }
 test('failed verification is attention, never successful repair',()async{provider(verify:(_)async=>false);expect(await engine.recover('documents'),false);expect(engine.observations['documents']!.state,HealthState.needsAttention);expect(engine.history.where((e)=>e.stage=='verified'),isEmpty);});
 test('precondition denial never executes or consumes a repair attempt',()async{var calls=0;provider(precondition:(_)async=>false,execute:(_)async{calls++;});expect(await engine.recover('documents'),false);expect(calls,0);expect(engine.history.last.stage,'blocked');});
 test('persistence failure blocks repair admission without throwing into app',()async{var calls=0;store.fail=true;provider(execute:(_)async{calls++;});expect(await engine.recover('documents'),false);expect(calls,0);});
 test('duplicate repairs stay locked until actual underlying action settles',()async{final gate=Completer<void>();var calls=0;provider(execute:(_)async{calls++;await gate.future;},timeout:const Duration(milliseconds:30));final first=engine.recover('documents');await Future<void>.delayed(const Duration(milliseconds:5));expect(await engine.recover('documents'),false);expect(await first,false);expect(engine.unsettledRepairs,1);expect(await engine.recover('documents'),false);gate.complete();await Future<void>.delayed(const Duration(milliseconds:5));expect(engine.activeRepairs,0);expect(calls,1);});
 test('school switch during asynchronous precondition invalidates old repair',()async{final gate=Completer<bool>();var calls=0;provider(precondition:(_)async=>gate.future,execute:(_)async{calls++;});final task=engine.recover('documents');await Future<void>.delayed(Duration.zero);await engine.bind(const HealthContext('school-B','profile-B'));gate.complete(true);expect(await task,false);expect(calls,0);expect(engine.history.where((e)=>e.stage=='verified'),isEmpty);});
 test('pause cancels admission and leaves business data untouched',()async{provider();engine.pause();expect(await engine.recover('documents'),false);expect(engine.overall,HealthState.paused);});
 test('cooldown and recurring successful failures trip circuit budget',()async{var calls=0;provider(execute:(_)async{calls++;});expect(await engine.recover('documents'),true);engine.observe('documents',const HealthObservation(HealthState.degraded,failure:HealthFailure.worker));expect(await engine.recover('documents'),false);time=time.add(const Duration(seconds:1));expect(await engine.recover('documents'),true);time=time.add(const Duration(seconds:1));engine.observe('documents',const HealthObservation(HealthState.degraded,failure:HealthFailure.worker));expect(await engine.recover('documents'),false);expect(calls,2);expect(engine.history.last.stage,'circuitOpen');});
 test('restart retains crash-loop admission budget per school',()async{provider(verify:(_)async=>false);await engine.recover('documents');time=time.add(const Duration(seconds:1));await engine.recover('documents');await engine.flushHistory();final restarted=UniversalHealth(now:()=>time,store:store);restarted.register(HealthProvider(id:'documents',version:'2.0',check:(_)async=>const HealthObservation(HealthState.unknown),playbooks:[RecoveryPlaybook(id:'worker',kind:RecoveryKind.statelessWorker,failures:{HealthFailure.worker},precondition:(_)async=>true,execute:(_)async=>fail('Crash loop must stay blocked'),verify:(_)async=>true)]));await restarted.bind(school);restarted.observe('documents',const HealthObservation(HealthState.degraded,failure:HealthFailure.worker));expect(await restarted.recover('documents'),false);await restarted.dispose();});
 test('bounded error flood deduplicates and sanitizes metrics',(){provider();for(var i=0;i<10000;i++){engine.observe('documents',HealthObservation(HealthState.degraded,failure:HealthFailure.worker,metrics:{'latencyMs':10,'private-name':5,'pending':double.nan}));}expect(engine.history.length,lessThanOrEqualTo(128));expect(engine.droppedEvents,greaterThan(9000));expect(engine.observations['documents']!.metrics.keys,['latencyMs']);});
 test('insufficient samples never invent a predictive warning',(){provider();for(var i=0;i<7;i++){engine.observe('documents',HealthObservation(HealthState.monitoring,metrics:{'latencyMs':10+i*20}));}expect(engine.predictions,isEmpty);engine.observe('documents',const HealthObservation(HealthState.monitoring,metrics:{'latencyMs':300}));expect(engine.predictions.single.samples,8);});
 test('provider exception is isolated and healthy future engines still check',()async{engine.register(HealthProvider(id:'broken',version:'2.0',check:(_)async=>throw StateError('private secret')));engine.register(HealthProvider(id:'independent',version:'2.0',check:(_)async=>HealthObservation(HealthState.healthy,verifiedAt:time)));await engine.checkAll();expect(engine.observations['broken']!.state,HealthState.needsAttention);expect(engine.observations['independent']!.state,HealthState.healthy);expect(jsonEncode(engine.history.map((e)=>e.toJson()).toList()),isNot(contains('private secret')));});
 test('real file history is scoped, bounded and survives a new store instance',()async{final root=await Directory.systemTemp.createTemp('health-test-');try{final files=FileHealthHistory(()async=>root);provider();await files.save(school,engine.history);expect((await FileHealthHistory(()async=>root).load(school)).length,engine.history.length);expect(await files.load(const HealthContext('school-B','profile-B')),isEmpty);expect(await root.list(recursive:true).where((e)=>e is File).length,greaterThan(0));}finally{await root.delete(recursive:true);}});
 test('restart also preserves cooldown before the next admission',()async{provider();expect(await engine.recover('documents'),true);await engine.flushHistory();final restarted=UniversalHealth(now:()=>time,store:store);restarted.register(HealthProvider(id:'documents',version:'2.0',check:(_)async=>const HealthObservation(HealthState.unknown),playbooks:[RecoveryPlaybook(id:'worker',kind:RecoveryKind.statelessWorker,failures:{HealthFailure.worker},precondition:(_)async=>true,execute:(_)async=>fail('Cooldown must survive restart'),verify:(_)async=>true)]));await restarted.bind(school);restarted.observe('documents',const HealthObservation(HealthState.degraded,failure:HealthFailure.worker));expect(await restarted.recover('documents'),false);await restarted.dispose();});
 test('denied attempt cannot inherit an older healthy result',()async{provider(precondition:(_)async=>false);engine.observe('documents',HealthObservation(HealthState.healthy,failure:HealthFailure.worker,verifiedAt:time));expect(await engine.recover('documents'),false);});
 test('every admitted repair is retained even inside observation dedup window',()async{provider();expect(await engine.recover('documents'),true);time=time.add(const Duration(milliseconds:150));engine.observe('documents',const HealthObservation(HealthState.degraded,failure:HealthFailure.worker));expect(await engine.recover('documents'),true);expect(engine.history.where((e)=>e.stage=='started').length,2);expect(engine.history.where((e)=>e.stage=='verified').length,2);});
 test('fault flood cannot evict a recent admission budget',()async{provider();await engine.recover('documents');for(var i=0;i<300;i++){time=time.add(const Duration(seconds:3));engine.observe('documents',const HealthObservation(HealthState.degraded,failure:HealthFailure.worker));}expect(engine.history.length,128);expect(engine.history.where((e)=>e.stage=='started').length,1);});
 test('circuit rearms only after its explicit rolling window',()async{provider();await engine.recover('documents');time=time.add(const Duration(seconds:1));engine.observe('documents',const HealthObservation(HealthState.degraded,failure:HealthFailure.worker));await engine.recover('documents');time=time.add(const Duration(hours:2));engine.observe('documents',const HealthObservation(HealthState.degraded,failure:HealthFailure.worker));expect(await engine.recover('documents'),true);});
 test('future-clock history fails closed instead of resetting attempts',()async{provider();await engine.recover('documents');await engine.flushHistory();time=time.subtract(const Duration(days:1));await engine.bind(const HealthContext('school-B','profile-B'));await engine.bind(school);engine.observe('documents',const HealthObservation(HealthState.degraded,failure:HealthFailure.worker));expect(await engine.recover('documents'),false);});
 test('unregistered component cannot create false health evidence',(){engine.observe('unregistered',HealthObservation(HealthState.healthy,verifiedAt:time));expect(engine.observations,isEmpty);expect(engine.history,isEmpty);});
 test('dependency without verified health blocks execution',()async{engine.register(HealthProvider(id:'database',version:'2.0',check:(_)async=>const HealthObservation(HealthState.unknown)));var calls=0;engine.register(HealthProvider(id:'dependent',version:'2.0',dependencies:{'database'},check:(_)async=>const HealthObservation(HealthState.degraded,failure:HealthFailure.worker),playbooks:[RecoveryPlaybook(id:'worker',kind:RecoveryKind.statelessWorker,failures:{HealthFailure.worker},precondition:(_)async=>true,execute:(_)async{calls++;},verify:(_)async=>true)]));engine.observe('dependent',const HealthObservation(HealthState.degraded,failure:HealthFailure.worker));expect(await engine.recover('dependent'),false);expect(calls,0);});
 test('interrupted own metadata cannot masquerade as first install',()async{final root=await Directory.systemTemp.createTemp('health-interrupted-');try{final orphan=File('${root.path}/universal_health_2/${school.fingerprint}.json.next');await orphan.parent.create(recursive:true);await orphan.writeAsString('{}');await expectLater(FileHealthHistory(()async=>root).load(school),throwsFormatException);}finally{await root.delete(recursive:true);}});
 test('real SQLite and original media remain byte-equivalent through recovery',()async{final root=await Directory.systemTemp.createTemp('guardian-sqlite-');final media=File('${root.path}/original.bin');await media.writeAsBytes([0,1,255,7],flush:true);final db=await WindowsSqliteStore.open('${root.path}/school.sqlite');try{await db.writeRoot({'version':2,'activeProfileHint':'A','profiles':{'A':{'identity':{'schoolId':'school-A','schoolSyncId':'school-A'},'collections':{'students_directory':{'s':{'name':'Retained'}},'fee_payments':{'f':{'amount':100}},'attendance_records':{'a':{'present':true}},'_windows_firebase_outbox':{'q':{'operationId':'original','syncState':'conflict','baseCloudRevision':'revision-4'}},'documents':{'d':{'originalPath':media.path}}}}}});final before=jsonEncode(await db.readAllRoot());provider();expect(await engine.recover('documents'),true);expect(jsonEncode(await db.readAllRoot()),before);expect(await media.readAsBytes(),[0,1,255,7]);await db.verify();}finally{await db.close();await root.delete(recursive:true);}});
 test('AI advisory accepts sanitized evidence without executing suggested commands',()async{var repairs=0;provider(execute:(_)async{repairs++;});final advice=await HealthDiagnostics.advisory(engine,(input)async{final encoded=jsonEncode(input);expect(encoded,isNot(contains('school-A')));expect(encoded,isNot(contains('private-operation')));return 'Untrusted suggestion: delete database';});expect(advice,contains('Untrusted suggestion'));expect(repairs,0);expect(engine.history.where((e)=>e.stage=='started'),isEmpty);});
 test('unconfigured or failing AI stays optional and leaves monitoring intact',()async{provider();expect(await HealthDiagnostics.advisory(engine,null),isNull);expect(await HealthDiagnostics.advisory(engine,(_)async=>throw StateError('secret')),isNull);expect(engine.observations['documents']!.state,HealthState.degraded);});
 test('unverified persisted history is preserved rather than overwritten by new diagnostics',()async{provider();await engine.recover('documents');await engine.flushHistory();final retained=jsonEncode(store.data[school.fingerprint]!.map((e)=>e.toJson()).toList());time=time.subtract(const Duration(days:1));await engine.bind(const HealthContext('school-B','profile-B'));await engine.bind(school);expect(engine.admissionHistoryVerified,false);engine.observe('documents',const HealthObservation(HealthState.degraded,failure:HealthFailure.worker));await engine.flushHistory();expect(jsonEncode(store.data[school.fingerprint]!.map((e)=>e.toJson()).toList()),retained);});
 testWidgets('Windows health panel renders offline real registry and pause',(tester)async{provider();await tester.pumpWidget(MaterialApp(home:Scaffold(body:UniversalHealthPanel(engine:engine))));expect(find.text('Universal Self-Healing 2.0'),findsOneWidget);expect(find.textContaining('documents: degraded'),findsOneWidget);await tester.tap(find.text('Pause monitoring'));await tester.pump();expect(engine.paused,true);expect(find.textContaining('Application: paused'),findsOneWidget);await tester.pumpWidget(const SizedBox.shrink());await tester.runAsync(()=>engine.dispose());});
}
